"""Prepare complete field crew packets from an exact saved Implementation revision."""
from __future__ import annotations

import argparse
from collections import defaultdict
from copy import deepcopy
from decimal import Decimal
import csv
import datetime as dt
from html import escape
import io
import json
import math
import os
import warnings
from pathlib import Path
import re
import tempfile

from .common import atomic_bytes, atomic_json, describe_file, digest, file_digest, read_json, verify_file
from .implementation import ImplementationStore, _fsync_directory
from .implementation_schema import ImplementationError, _safe_id, document_digest, validate_plan
from .implementation_observations import _attachment_inventory
from .monitoring_packet import add_member, file_member, retain_packet

SCHEMA = "upstate.field-deployment/v1"
VERSION = "field-crew-packet/2-declared-coordinates"
HEX = re.compile(r"[0-9a-f]{64}")
APPLICATION = Path(__file__).resolve().parents[1]


def _selection(value):
    if not isinstance(value, dict) or set(value) - {"visit_ids", "title"}:
        raise ImplementationError("Choose the original visit IDs and a crew-packet title")
    ids = value.get("visit_ids")
    if not isinstance(ids, list) or not ids or any(not isinstance(key, str) for key in ids):
        raise ImplementationError("Select at least one original saved visit")
    if len(ids) != len(set(ids)):
        raise ImplementationError("Select each original visit once")
    title = value.get("title", "Field crew packet")
    if not isinstance(title, str) or not title.strip():
        raise ImplementationError("Name the field crew packet")
    return {"title": title.strip(), "visit_ids": list(ids)}


def _root(workspace, plan_id, key):
    _safe_id(plan_id, "plan_id")
    if not isinstance(key, str) or not HEX.fullmatch(key):
        raise ImplementationError("Choose a retained field deployment identity")
    root = workspace.root.resolve()
    directory = root / "implementation" / "plans" / plan_id / "deployments" / key
    if not directory.resolve().is_relative_to(root) or directory.is_symlink():
        raise ImplementationError("The field packet must remain in its original plan bank")
    return directory


def _text(value):
    return "" if value is None else json.dumps(value, ensure_ascii=False, sort_keys=True) if isinstance(value, (dict, list)) else str(value)


def _calendar(visit):
    value = visit.get("original_calendar")
    return value if isinstance(value, dict) else {}



SUPPORTED_GEOGRAPHIC_CRS = {"EPSG:4326", "EPSG:4269", "EPSG:4267", "EPSG:4258"}


def _grid_metadata(grid):
    return {key: getattr(grid, key, None) for key in
            ("short_name", "full_name", "package_name", "url",
             "direct_download", "open_license", "available")}


def _coordinate_record(site):
    """Derive a WGS84 point from its explicit original geographic declaration."""
    lat, lon = site.get("latitude"), site.get("longitude")
    declared = site.get("coordinate_reference_system")
    record = {
        "site_id": site["id"],
        "original": {"latitude": lat, "longitude": lon,
                     "coordinate_reference_system": deepcopy(declared)},
        "state": "missing_coordinates", "wgs84": None,
        "transformation": None, "message": "",
    }
    if lat is None or lon is None:
        record["message"] = "The original site has no complete point coordinate."
        return record
    if (isinstance(lat, bool) or isinstance(lon, bool)
            or not isinstance(lat, (int, float)) or not isinstance(lon, (int, float))
            or not math.isfinite(lat) or not math.isfinite(lon)
            or not -90 <= lat <= 90 or not -180 <= lon <= 180):
        record.update(state="invalid_coordinates",
                      message="Original geographic coordinates are not finite valid degrees.")
        return record
    if not isinstance(declared, str) or not declared.strip():
        record.update(state="undeclared_crs",
                      message="The original site datum is unstated. Original degrees are retained without a GeoJSON point or calendar GEO.")
        return record
    source_crs = declared.strip().upper()
    if source_crs not in SUPPORTED_GEOGRAPHIC_CRS:
        record.update(state="unsupported_crs",
                      message="This geographic datum declaration needs an explicit supported transformation; original coordinates are retained without relabeling.")
        return record
    if source_crs == "EPSG:4326":
        record.update(
            state="original_wgs84", wgs84={"longitude": lon, "latitude": lat},
            transformation={"source_crs": source_crs, "target_crs": "EPSG:4326",
                            "method": "Original explicitly declared WGS84 degrees; no datum conversion",
                            "always_xy": True},
            message="Original explicitly declared WGS84 coordinates are used unchanged.")
        return record
    try:
        import pyproj
        from pyproj.aoi import AreaOfInterest
        from pyproj.transformer import TransformerGroup
        # A point-local area avoids selecting an operation for another geographic region.
        area = AreaOfInterest(max(-180, lon - 0.000001), max(-90, lat - 0.000001),
                              min(180, lon + 0.000001), min(90, lat + 0.000001))
        with warnings.catch_warnings(record=True) as observed:
            warnings.simplefilter("always")
            group = TransformerGroup(source_crs, "EPSG:4326", always_xy=True,
                                     area_of_interest=area, allow_ballpark=False)
        unavailable = [
            {"name": operation.name, "accuracy_m": operation.accuracy,
             "grids": [_grid_metadata(grid) for grid in operation.grids]}
            for operation in group.unavailable_operations
        ]
        runtime = {
            "source_crs": source_crs, "target_crs": "EPSG:4326", "always_xy": True,
            "allow_ballpark": False, "pyproj_version": pyproj.__version__,
            "proj_version": pyproj.proj_version_str,
            "best_available": group.best_available,
            "warnings": [str(item.message) for item in observed],
            "unavailable_operations": unavailable,
        }
        record["transformation"] = runtime
        failures = []
        for transformer in group.transformers:
            extent = transformer.area_of_use
            if extent is not None:
                longitude_inside = (extent.west <= lon <= extent.east if extent.west <= extent.east
                                    else lon >= extent.west or lon <= extent.east)
                if not longitude_inside or not extent.south <= lat <= extent.north:
                    continue
            try:
                x, y = transformer.transform(lon, lat, errcheck=True)
            except Exception as error:
                failures.append({"operation": transformer.description, "message": str(error)})
                continue
            if not (math.isfinite(x) and math.isfinite(y) and -180 <= x <= 180 and -90 <= y <= 90):
                failures.append({"operation": transformer.description, "message": "Output is not a finite WGS84 longitude/latitude point"})
                continue
            operation_grids = [_grid_metadata(grid) for operation in transformer.operations
                               for grid in operation.grids]
            runtime.update(
                description=transformer.description, definition=transformer.definition,
                accuracy_m=transformer.accuracy if transformer.accuracy >= 0 else None,
                area_of_use=({"name": extent.name, "west": extent.west, "south": extent.south,
                              "east": extent.east, "north": extent.north} if extent else None),
                grids=operation_grids, rejected_operations=failures)
            record.update(state="transformed", wgs84={"longitude": x, "latitude": y},
                          message="Original declared " + source_crs + " coordinates were transformed to WGS84 using the retained native operation.")
            if not group.best_available:
                record["message"] += " A preferred known operation is unavailable; the selected available operation and declared accuracy are retained."
            return record
        runtime["rejected_operations"] = failures
        record.update(state="transform_unavailable",
                      message="No available non-ballpark native operation covers and transforms this original site. Original coordinates are retained without a GeoJSON point or calendar GEO.")
    except ImportError as error:
        record.update(state="transform_unavailable",
                      message="The native coordinate transformation runtime is unavailable: " + str(error))
    except Exception as error:
        record.update(state="transform_unavailable",
                      message="The declared native coordinate transformation could not be completed: " + str(error))
    return record


def _coordinate_inventory(sites):
    return {
        "schema": "upstate.field-deployment-coordinates/v1",
        "geojson_crs": "OGC:CRS84", "geojson_axis_order": ["longitude", "latitude"],
        "calendar_geo_crs": "EPSG:4326", "calendar_geo_axis_order": ["latitude", "longitude"],
        "policy": "Only explicitly declared WGS84 or a retained non-ballpark native transform supplies exported geometry; original site records remain unchanged",
        "sites": [_coordinate_record(site) for site in sites],
    }


def _coordinate_index(context):
    inventory = context.get("coordinate_inventory")
    if inventory is None:
        inventory = _coordinate_inventory(context["sites"])
    return {row["site_id"]: row for row in inventory["sites"]}


def _coordinate_label(record):
    if record["wgs84"] is None:
        return record["state"].replace("_", " ") + "; no exported point"
    value = record["wgs84"]
    label = _text(value["latitude"]) + " / " + _text(value["longitude"]) + " (WGS84)"
    operation = record.get("transformation") or {}
    if operation.get("accuracy_m") is not None:
        label += "; operation accuracy " + _text(operation["accuracy_m"]) + " m"
    return label


def _context(workspace, plan_id, revision, selection):
    selected = _selection(selection)
    store = ImplementationStore(workspace)
    plan = store.get(plan_id, revision)
    if revision != plan["revision"]:
        raise ImplementationError("Choose the exact saved native revision")
    wanted = set(selected["visit_ids"])
    available = {row["id"] for row in plan["visits"]}
    if wanted - available:
        raise ImplementationError("Selected visits are absent from this saved revision")
    # Retain declared selection order; the printable grouping preserves it within a crew/day.
    index = {row["id"]: row for row in plan["visits"]}
    visits = [deepcopy(index[key]) for key in selected["visit_ids"]]
    site_ids = {row["site_id"] for row in visits}
    monitor_ids = {row.get("monitoring_plan_id") for row in visits}
    sites = [deepcopy(row) for row in plan["sites"] if row["id"] in site_ids]
    protocols = [deepcopy(row) for row in plan["monitoring_plans"] if row["id"] in monitor_ids]
    activities = [deepcopy(row) for row in plan["activities"] if row["visit_id"] in wanted]
    activity_ids = {row["id"] for row in activities}
    observations = [deepcopy(row) for row in plan["observations"] if row["activity_id"] in activity_ids]
    attachments, files = _attachment_inventory(workspace, plan)
    from build_implementation_offline import PARTS
    offline = {name: describe_file(APPLICATION, APPLICATION / name)
               for name in ["build_implementation_offline.py", *PARTS.values()]}
    binding = {"plan_id": plan["id"], "title": plan["title"], "revision": plan["revision"],
               "document_digest": document_digest(plan)}
    revision_path = store.base / plan["id"] / "revisions" / ("%016d.json" % plan["revision"])
    coordinate_inventory = _coordinate_inventory(sites)
    coordinates = {row["site_id"]: row for row in coordinate_inventory["sites"]}
    identity = {"version": VERSION, "implementation_sha256": file_digest(__file__),
                "workspace_id": workspace.project["id"], "plan": binding, "selection": selected,
                "original_revision": describe_file(workspace.root, revision_path),
                "attachment_inventory": attachments, "offline_application_sources": offline,
                "coordinate_inventory": coordinate_inventory}
    site_index = {row["id"]: row for row in sites}
    issues = []
    for visit in visits:
        site = site_index[visit["site_id"]]
        for code, condition, message in (
            ("planned_date", not visit.get("planned_date"), "Set the planned date to include this visit in the calendar."),
            ("observer", not visit.get("observer"), "The original observer assignment is blank."),
            ("coordinate", site.get("latitude") is None, "This original site has no point coordinate; review its retained source/search area."),
            ("protocol", not visit.get("monitoring_plan_id"), "This visit has no linked monitoring protocol."),
        ):
            if condition:
                issues.append({"visit_id": visit["id"], "code": code, "message": message})
        coordinate = coordinates[site["id"]]
        if coordinate["state"] != "missing_coordinates" and coordinate["wgs84"] is None:
            issues.append({"visit_id": visit["id"], "site_id": site["id"],
                           "code": "coordinate_" + coordinate["state"],
                           "message": coordinate["message"]})
        elif coordinate["state"] == "transformed" and not coordinate["transformation"]["best_available"]:
            issues.append({"visit_id": visit["id"], "site_id": site["id"],
                           "code": "coordinate_available_accuracy", "message": coordinate["message"]})
        if _calendar(visit).get("start_local") or _calendar(visit).get("finish_local"):
            issues.append({"visit_id": visit["id"], "code": "local_clock",
                           "message": "Original local clock values are printed. Calendar events use the planned date; no time zone is assigned."})
    for activity in activities:
        if activity["kind"] == "sample" and not activity.get("custody_ref"):
            issues.append({"visit_id": activity["visit_id"], "activity_id": activity["id"],
                           "code": "custody", "message": "This retained sample has no recorded custody reference."})
    groups = defaultdict(list)
    for visit in visits:
        calendar = _calendar(visit)
        groups[(visit.get("planned_date") or "", _text(calendar.get("crew")), visit.get("observer") or "")].append(visit["id"])
    summary = {"visits": len(visits), "sites": len(sites), "protocols": len(protocols),
               "activities": len(activities), "observations": len(observations),
               "mapped_sites": sum(row["wgs84"] is not None for row in coordinate_inventory["sites"]),
               "original_coordinate_sites": sum(row.get("latitude") is not None for row in sites),
               "unmapped_coordinate_sites": sum(row.get("latitude") is not None and coordinates[row["id"]]["wgs84"] is None for row in sites),
               "transformed_sites": sum(row["state"] == "transformed" for row in coordinate_inventory["sites"]),
               "calendar_events": sum(bool(row.get("planned_date")) for row in visits),
               "available_attachments": len(files),
               "groups": [{"planned_date": day or None, "crew": crew or None, "observer": observer or None,
                           "visit_ids": ids} for (day, crew, observer), ids in sorted(groups.items())]}
    return {"id": digest(identity), "identity": identity, "selection": selected, "plan": binding,
            "original_plan": plan, "revision_path": revision_path,
            "visits": visits, "sites": sites, "monitoring_plans": protocols,
            "activities": activities, "observations": observations,
            "attachment_inventory": attachments, "attachment_files": files,
            "summary": summary, "issues": issues, "coordinate_inventory": coordinate_inventory}


def preview(workspace, plan_id, revision, selection):
    value = _context(workspace, plan_id, revision, selection)
    return {"schema": SCHEMA, "state": "preview",
            **{name: value[name] for name in ("id", "plan", "selection", "summary", "issues",
                                             "visits", "sites", "monitoring_plans", "attachment_inventory", "coordinate_inventory")}}


def _copy_file(source, target, descriptor):
    if target.exists():
        verify_file(target.parent, {**descriptor, "path": target.name})
        return
    target.parent.mkdir(parents=True, exist_ok=True)
    fd, temporary = tempfile.mkstemp(prefix=".field-deployment-", dir=target.parent)
    pending = Path(temporary)
    try:
        import hashlib
        checksum, size = hashlib.sha256(), 0
        with os.fdopen(fd, "wb") as outgoing, Path(source).open("rb") as incoming:
            for body in iter(lambda: incoming.read(1024 * 1024), b""):
                outgoing.write(body); checksum.update(body); size += len(body)
            outgoing.flush(); os.fsync(outgoing.fileno())
        if size != descriptor["bytes"] or checksum.hexdigest() != descriptor["sha256"]:
            raise ImplementationError("An original field deployment source changed")
        os.replace(pending, target)
        _fsync_directory(target.parent)
    finally:
        pending.unlink(missing_ok=True)


def _csv(rows, preferred):
    fields = list(dict.fromkeys([*preferred, *(key for row in rows for key in row)]))
    output = io.StringIO(newline="")
    writer = csv.writer(output, lineterminator="\r\n")
    writer.writerow(fields)
    for row in rows:
        # Preserve original strings, nested records and nulls in the complete companion JSON.
        writer.writerow([("'" + row[key] if isinstance(row.get(key), str) and row[key].lstrip().startswith(("=", "+", "-", "@"))
                          else _text(row.get(key))) for key in fields])
    return output.getvalue().encode("utf-8-sig")


def _ical_text(value):
    text = _text(value).replace("\r\n", "\n").replace("\r", "\n")
    text = "".join(char if ord(char) >= 32 or char in "\n\t" else " " for char in text)
    return text.replace("\\", "\\\\").replace("\n", "\\n").replace(";", "\\;").replace(",", "\\,")


def _fold(value):
    lines, line, size = [], "", 0
    for char in value:
        width = len(char.encode("utf-8"))
        if size + width > 75:
            lines.append(line); line, size = " ", 1
        line += char; size += width
    return "\r\n".join([*lines, line])


def _calendar_coordinate(value):
    """RFC5545 FLOAT uses decimal digits, without scientific exponent notation."""
    return format(Decimal(str(value)), "f")


def calendar_bytes(context):
    """RFC5545 date events; original local clocks remain explicit description fields."""
    plan = context["original_plan"]
    timestamp = dt.datetime.fromisoformat(plan["updated_at"].replace("Z", "+00:00")).astimezone(dt.timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    lines = ["BEGIN:VCALENDAR", "VERSION:2.0", "PRODID:-//Upper Savannah//Field crew packet//EN",
             "CALSCALE:GREGORIAN"]
    sites = {row["id"]: row for row in context["sites"]}
    coordinates = _coordinate_index(context)
    for visit in context["visits"]:
        if not visit.get("planned_date"):
            continue
        site, original = sites[visit["site_id"]], _calendar(visit)
        uid = digest({"workspace": context["identity"]["workspace_id"], "plan": plan["id"], "visit": visit["id"]})
        description = "\n".join([
            "Plan: " + plan["title"] + "; revision " + str(plan["revision"]),
            "Original visit: " + visit["id"], "Recorded status: " + visit["status"],
            "Observer: " + visit.get("observer", ""), "Original crew: " + _text(original.get("crew")),
            "Original local start: " + _text(original.get("start_local")),
            "Original local finish: " + _text(original.get("finish_local")),
            "Original calendar: " + _text(original), "Notes: " + visit.get("notes", ""),
            "Original latitude/longitude: " + _text(site.get("latitude")) + " / " + _text(site.get("longitude")),
            "Original coordinate reference system: " + _text(site.get("coordinate_reference_system")),
            "Exported coordinate: " + _coordinate_label(coordinates[site["id"]]),
            "Open the retained crew packet and existing field workbench for original protocol and actual field capture.",
        ])
        lines.extend(["BEGIN:VEVENT", "UID:" + uid + "@upstate-field",
                      "DTSTAMP:" + timestamp, "LAST-MODIFIED:" + timestamp,
                      "DTSTART;VALUE=DATE:" + visit["planned_date"].replace("-", ""),
                      "SUMMARY:" + _ical_text(site["label"] + " — " + plan["title"]),
                      "LOCATION:" + _ical_text(site["label"]),
                      "DESCRIPTION:" + _ical_text(description), "TRANSP:TRANSPARENT"])
        if visit["status"] == "cancelled":
            lines.append("STATUS:CANCELLED")
        point = coordinates[site["id"]]["wgs84"]
        if point is not None:
            lines.append("GEO:" + _calendar_coordinate(point["latitude"]) + ";" + _calendar_coordinate(point["longitude"]))
        lines.append("END:VEVENT")
    lines.append("END:VCALENDAR")
    return ("\r\n".join(_fold(line) for line in lines) + "\r\n").encode("utf-8")


def _table(headers, rows):
    return ('<div class="table"><table><thead><tr>' + "".join("<th>" + escape(_text(x)) + "</th>" for x in headers)
            + "</tr></thead><tbody>" + "".join("<tr>" + "".join("<td>" + escape(_text(x)) + "</td>" for x in row)
                                                + "</tr>" for row in rows) + "</tbody></table></div>")


def render_html(context):
    plan = context["original_plan"]
    coordinates = _coordinate_index(context)
    sites = {row["id"]: row for row in context["sites"]}
    protocols = {row["id"]: row for row in context["monitoring_plans"]}
    visits = {row["id"]: row for row in context["visits"]}
    parts = ['<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">',
             "<title>" + escape(context["selection"]["title"]) + "</title>",
             "<style>body{font:15px/1.5 system-ui,sans-serif;max-width:1120px;margin:32px auto;padding:0 20px;color:#222;background:#fff}h1,h2,h3{line-height:1.25}h2{border-top:2px solid #555;padding-top:18px}a{color:#222}table{border-collapse:collapse;width:100%;margin:12px 0}th,td{border:1px solid #aaa;padding:7px;text-align:left;vertical-align:top;overflow-wrap:anywhere}th{background:#eee}.table{overflow:auto}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}.sheet{border:1px solid #888;padding:18px;margin:20px 0}.line{min-height:38px;border-bottom:1px solid #aaa}.muted{color:#555}@media print{body{font-size:11px;margin:0;max-width:none}.screen{display:none}.sheet{break-before:page;border:0;padding:0}thead{display:table-header-group}tr{break-inside:avoid}.table{overflow:visible}a{color:#222;text-decoration:none}}</style>",
             "<h1>" + escape(context["selection"]["title"]) + "</h1>",
             "<p>" + escape(plan["title"]) + " · saved revision " + str(plan["revision"]) + "</p>",
             '<p class="screen"><a href="field-workbench.html">Open field workbench</a> · <a href="original-plan.json" download>Complete editable plan</a> · <a href="visits.ics" download>Calendar</a> · <a href="sites.geojson" download>Site geometry</a></p>',
             "<p>Open the field workbench to continue the included original plan. Choose a selected visit in the packet toolbar, record actual visits, samples and observations, then export the completed plan and files as a complete ZIP. Import that ZIP in the original Workspace and review its saved revision before returning completed work to its original Monitoring campaign.</p>",
             "<p>The packet groups original visits by planned date, original crew and observer. Local clock values remain as recorded. Calendar events cover the stated day. Source search areas remain identified where no station point is available.</p>",
             "<p>Original site coordinates and their declared datum are retained. GeoJSON and calendar coordinates use WGS84 only after an explicit declaration or a recorded native transformation. Unstated or unavailable transformations leave geometry empty; coordinate-inventory.json retains each original coordinate and operation.</p>"]
    parts.append(_table(["Day", "Original crew", "Observer", "Visits"], [
        [row["planned_date"], row["crew"], row["observer"], len(row["visit_ids"])] for row in context["summary"]["groups"]]))
    parts.append("<h2>Preparation notes</h2>" + _table(["Visit / activity", "Recorded preparation detail"], [
        [row.get("activity_id") or row["visit_id"], row["message"]] for row in context["issues"]]))
    parts.append("<h2>Selected sites</h2>" + _table(["Site", "Original latitude / longitude", "Declared CRS", "Exported coordinate", "Geometry role", "Original source"], [
        [site["label"], _text(site.get("latitude")) + " / " + _text(site.get("longitude")),
         site.get("coordinate_reference_system") or "Unstated", _coordinate_label(coordinates[site["id"]]),
         site.get("geometry_role"), site.get("source_ref")] for site in context["sites"]]))
    for group in context["summary"]["groups"]:
        for key in group["visit_ids"]:
            visit, site = visits[key], sites[visits[key]["site_id"]]
            protocol = protocols.get(visit.get("monitoring_plan_id"))
            original = _calendar(visit)
            parts.append('<section class="sheet"><h2>' + escape(site["label"]) + "</h2>")
            parts.append(_table(["Field", "Original saved value"], [
                ["Visit ID", visit["id"]], ["Planned date", visit.get("planned_date")],
                ["Original crew", original.get("crew")], ["Observer", visit.get("observer")],
                ["Original local start / finish", _text(original.get("start_local")) + " / " + _text(original.get("finish_local"))],
                ["Recorded status", visit["status"]], ["Recorded actual visit", visit.get("visited_at")],
                ["Site ID", site["id"]], ["Original latitude / longitude", _text(site.get("latitude")) + " / " + _text(site.get("longitude"))],
                ["Original coordinate reference system", site.get("coordinate_reference_system") or "Unstated"],
                ["Exported WGS84 coordinate", _coordinate_label(coordinates[site["id"]])],
                ["Coordinate interpretation", coordinates[site["id"]]["message"]],
                ["Site geometry role", site.get("geometry_role")], ["Visit notes", visit.get("notes")],
                ["Evidence references", visit.get("evidence_refs", [])],
            ]))
            if protocol:
                parts.append("<h3>Monitoring protocol</h3>" + _table(["Field", "Original saved value"], [
                    [key.replace("_", " "), value] for key, value in protocol.items()]))
            parts.append("<h3>Original activities and sample custody</h3>" + _table(
                ["Activity", "Kind", "Sample ID", "Collected at", "Method", "Custody reference", "Notes"],
                [[row["id"], row["kind"], row.get("sample_id"), row.get("collected_at"), row.get("method"),
                  row.get("custody_ref"), row.get("notes")] for row in context["activities"] if row["visit_id"] == visit["id"]]))
            parts.append("<h3>Field entries</h3><p>Enter observations in the complete editable plan. These blank lines are available for handwritten capture.</p>"
                         '<p class="line">Actual date/time and time zone:</p><p class="line">Observer / crew:</p>'
                         '<p class="line">Activity / sample identifiers and custody:</p><p class="line">Field conditions / notes:</p>'
                         '<p class="line">Follow-up:</p><details><summary>Complete original site and visit</summary><pre>'
                         + escape(json.dumps({"site": site, "visit": visit}, ensure_ascii=False, indent=2)) + "</pre></details></section>")
    parts.append("<h2>Original sources and attachments</h2>" + _table(["Source", "Kind", "Reference"], [
        [row["label"], row["kind"], row.get("reference")] for row in plan["source_links"]]))
    parts.append(_table(["Original local attachment", "Availability"], [
        [row["label"], row["state"].replace("_", " ")] for row in context["attachment_inventory"]]))
    parts.append('<p>selected-records.json retains every original selected row field. original-plan.json contains the complete saved plan, source snapshots and result records. packet-index.json lists all retained file identities.</p></html>')
    return "".join(parts).encode("utf-8")


def prepare(workspace, plan_id, revision, selection, *, expected_id):
    selected = _selection(selection)
    store = ImplementationStore(workspace)
    # Same lock used by plan editing and whole-Workspace capture.
    with store._locked(plan_id):
        directory = _root(workspace, plan_id, expected_id)
        if (directory / "deployment.json").exists():
            result = inspect(workspace, plan_id, expected_id)
            if result["plan"]["revision"] != revision or result["selection"] != selected:
                raise ImplementationError("The retained field packet belongs to another original request")
            return dict(result, reused=True)
        context = _context(workspace, plan_id, revision, selected)
        if context["id"] != expected_id:
            raise ImplementationError("The saved field selection or source files changed after preview")
        directory.mkdir(parents=True, exist_ok=True)
        atomic_json(directory / "intent.json", context["identity"], immutable=True)
        atomic_json(directory / "original-plan.json", context["original_plan"], immutable=True)
        _copy_file(context["revision_path"], directory / "original-revision.json",
                   context["identity"]["original_revision"])
        records = {name: context[name] for name in ("visits", "sites", "monitoring_plans", "activities", "observations")}
        atomic_json(directory / "selected-records.json", records, immutable=True)
        atomic_json(directory / "selection.json", context["selection"], immutable=True)
        atomic_json(directory / "attachment-inventory.json", context["attachment_inventory"], immutable=True)
        atomic_json(directory / "preparation.json", {"summary": context["summary"], "issues": context["issues"]}, immutable=True)
        atomic_json(directory / "coordinate-inventory.json", context["coordinate_inventory"], immutable=True)
        for name, headers in (
            ("visits", ["id", "planned_date", "site_id", "observer", "status", "monitoring_plan_id"]),
            ("sites", ["id", "label", "latitude", "longitude", "coordinate_reference_system", "geometry_role"]),
            ("monitoring_plans", ["id", "title", "objective", "parameters", "method_ref"]),
            ("activities", ["id", "visit_id", "site_id", "kind", "sample_id", "collected_at", "method", "custody_ref"]),
            ("observations", ["id", "activity_id", "parameter", "result_type", "original_text", "unit"]),
        ):
            atomic_bytes(directory / (name + ".csv"), _csv(records[name], headers), immutable=True)
        coordinates = _coordinate_index(context)
        features = []
        for site in context["sites"]:
            coordinate = coordinates[site["id"]]
            point = coordinate["wgs84"]
            features.append({
                "type": "Feature", "id": site["id"],
                "geometry": ({"type": "Point", "coordinates": [point["longitude"], point["latitude"]]}
                             if point is not None else None),
                "properties": {**site, "deployment_coordinate": coordinate,
                               "deployment_visit_ids": [row["id"] for row in context["visits"]
                                                        if row["site_id"] == site["id"]]},
            })
        atomic_json(directory / "sites.geojson", {"type": "FeatureCollection", "features": features}, immutable=True)
        atomic_bytes(directory / "visits.ics", calendar_bytes(context), immutable=True)
        atomic_bytes(directory / "crew-packet.html", render_html(context), immutable=True)
        # Retain the complete existing offline editor from the exact reviewed installed sources.
        from build_implementation_offline import build
        built_path = directory / "field-workbench.html"
        built = build(APPLICATION, built_path, field_packet={
            "schema": "upstate.offline-field-packet/v1",
            "workspace_id": workspace.project["id"], "deployment_id": context["id"],
            "plan": context["original_plan"], "visit_ids": context["selection"]["visit_ids"],
        }, field_files=context["attachment_files"])
        atomic_json(directory / "offline-build.json", {name: built[name] for name in
                    ("schema", "bytes", "sha256", "inputs", "field_packet")}, immutable=True)
        for name, descriptor in context["identity"]["offline_application_sources"].items():
            verify_file(APPLICATION, descriptor)
        for path, descriptor in context["attachment_files"]:
            _copy_file(path, directory / descriptor["retained_path"], descriptor)
        names = ["intent.json", "original-plan.json", "original-revision.json", "selected-records.json",
                 "selection.json", "attachment-inventory.json", "preparation.json", "coordinate-inventory.json",
                 "visits.csv", "sites.csv", "monitoring_plans.csv", "activities.csv", "observations.csv",
                 "sites.geojson", "visits.ics", "crew-packet.html", "field-workbench.html", "offline-build.json"]
        names.extend(row["retained_path"] for row in context["attachment_inventory"] if row["state"] == "retained")
        members = {name: describe_file(directory, directory / name) for name in dict.fromkeys(names)}
        index = {"schema": SCHEMA, "id": context["id"], "identity": context["identity"],
                 "files": members, "summary": context["summary"], "issues": context["issues"]}
        atomic_json(directory / "packet-index.json", index, immutable=True)
        members["packet-index.json"] = describe_file(directory, directory / "packet-index.json")
        package = {}
        for name, descriptor in members.items():
            add_member(package, name, file_member(directory / name, descriptor["bytes"], descriptor["sha256"]))
        retain_packet(directory / "crew-packet.zip", package)
        members["crew-packet.zip"] = describe_file(directory, directory / "crew-packet.zip")
        result = {"schema": SCHEMA, "id": context["id"], "state": "complete",
                  "identity": context["identity"], "plan": context["plan"], "selection": context["selection"],
                  "summary": context["summary"], "issues": context["issues"], "files": members}
        result["record_sha256"] = digest(result)
        atomic_json(directory / "deployment.json", result, immutable=True)
        return result


def inspect(workspace, plan_id, key, *, verify=True):
    directory = _root(workspace, plan_id, key)
    result = read_json(directory / "deployment.json")
    if (result.get("schema") != SCHEMA or result.get("state") != "complete" or result.get("id") != key
            or digest(result["identity"]) != key or result["identity"]["workspace_id"] != workspace.project["id"]
            or result["plan"] != result["identity"]["plan"] or result["plan"]["plan_id"] != plan_id
            or result["selection"] != result["identity"]["selection"]
            or digest({k: v for k, v in result.items() if k != "record_sha256"}) != result.get("record_sha256")):
        raise ImplementationError("The retained field packet differs from its original saved selection")
    if verify:
        plan = ImplementationStore(workspace).get(plan_id, result["plan"]["revision"])
        if document_digest(plan) != result["plan"]["document_digest"]:
            raise ImplementationError("The original saved field revision changed")
        for descriptor in result["files"].values():
            verify_file(directory, descriptor)
        if validate_plan(read_json(directory / "original-plan.json")) != plan:
            raise ImplementationError("The packet's complete plan differs from the saved revision")
    return result


def catalog(workspace, plan_id):
    store = ImplementationStore(workspace)
    store.get(plan_id)
    return [{name: row[name] for name in ("id", "plan", "selection", "summary")}
            for path in sorted((store.base / plan_id / "deployments").glob("*/deployment.json"))
            for row in [inspect(workspace, plan_id, path.parent.name, verify=False)]]


def main(argv=None):
    from .workspace import Workspace
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--workspace", required=True)
    parser.add_argument("--plan-id", required=True)
    parser.add_argument("--revision", type=int)
    parser.add_argument("--visit", action="append", default=[])
    parser.add_argument("--title", default="Field crew packet")
    parser.add_argument("--expected-id")
    parser.add_argument("--inspect-id")
    args = parser.parse_args(argv)
    workspace = Workspace(args.workspace)
    if args.inspect_id:
        result = inspect(workspace, args.plan_id, args.inspect_id)
    else:
        selection = {"title": args.title, "visit_ids": args.visit}
        result = (prepare(workspace, args.plan_id, args.revision, selection, expected_id=args.expected_id)
                  if args.expected_id else preview(workspace, args.plan_id, args.revision, selection))
    print(json.dumps(result, ensure_ascii=False, indent=2, allow_nan=False))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Carry saved Gauge report sources into the existing editable Study transfer.

The dispatcher calls include_source only for explicitly ordered scientific-report
sources. Original CAS bytes, saved selections and result records remain unchanged.
This adapter uses the established closure and its portable snapshot/reopen path.
"""
from __future__ import annotations

from copy import deepcopy
from pathlib import PurePosixPath
import re

from .common import digest, identifier

CONTEXT = "gauge_support"
ROLE = "gauge-support-report-context"
REPORT_SCHEMA = "upstate.observed-report/v1"
GAUGE_SCHEMA = "upstate.gauge-support/v1"
PACKAGE_SCHEMA = "upstate.gauge-support-package/v1"
REPORT_EDITIONS = ("gauge-support-report-1.0.0", "gauge-support-report-1.1.0")


def _member(value):
    if not isinstance(value, str) or "\\" in value or "\0" in value:
        raise ValueError("Gauge source needs canonical original member paths")
    path = PurePosixPath(value)
    if (not path.parts or path.is_absolute() or ".." in path.parts
            or path.as_posix() != value or any(":" in part for part in path.parts)):
        raise ValueError("Gauge source member must remain inside its original edition")
    return value


def _same(left, right):
    return all(left.get(field) == right.get(field) for field in ("bytes", "sha256"))


def _body(closure, descriptor):
    closure.add_file(descriptor["object"], descriptor)
    return closure.read(descriptor["object"])


def _immutable(closure, kind, key):
    key = identifier(key)
    value = closure.read(kind + "/" + key + ".json")
    if value.get("schema") != "upstate." + kind + "/v1" or digest(value) != key:
        raise ValueError("Gauge source lost its original editable " + kind + " record")
    return {**value, "id": key}


def _members(closure, entry, recipe):
    members = {}
    for item in entry.get("companions", []):
        name = _member(item.get("view_path", item["filename"]))
        if name in members:
            raise ValueError("Gauge source repeats an original companion")
        closure.add_file(item["object"], item)
        members[name] = item
    inputs = recipe.get("inputs")
    if not isinstance(inputs, list) or not inputs:
        raise ValueError("Gauge report needs its complete original companion inventory")
    declared = {}
    for item in inputs:
        name = _member(item["path"])
        if name in declared or name not in members or not _same(item, members[name]):
            raise ValueError("Gauge report lost an exact original input: " + name)
        declared[name] = item
    if set(declared) != set(members):
        raise ValueError("Gauge report companions differ from its original source recipe")
    return members


def _original(closure, members, name):
    name = _member(name)
    if name not in members:
        raise ValueError("Gauge source lacks its original member: " + name)
    return _body(closure, members[name])


def _package(closure, members, recipe):
    package = _original(closure, members, "retained/package.json")
    analysis = _original(closure, members, "retained/analysis.json")
    regional = _original(closure, members, "retained/regional-report.json")
    project = recipe["project_id"]
    key = identifier(recipe.get("gauge_support_id"))
    build_id = identifier(recipe.get("gauge_build_id"))
    station_id = identifier(recipe.get("station_edition_id"))
    if (package.get("schema") != PACKAGE_SCHEMA or package.get("project_id") != project
            or package.get("build_id") != build_id
            or package.get("selection") != recipe.get("original_selection")
            or package.get("station_edition_id") != station_id
            or package.get("regional") != recipe.get("regional")):
        raise ValueError("Gauge report changed its retained original package identity")
    if (analysis.get("schema") != GAUGE_SCHEMA or analysis.get("project_id") != project
            or analysis.get("build_id") != build_id
            or analysis.get("selection") != package["selection"]
            or analysis.get("station_edition_id") != station_id
            or analysis.get("regional") != package["regional"]
            or analysis.get("summary") != recipe.get("summary")
            or recipe.get("title") != analysis.get("title", "") + " — gauge support"):
        raise ValueError("Gauge report differs from its original calculated result")
    if "support" in recipe and recipe["support"] != analysis.get("support"):
        raise ValueError("Gauge report changed its original catchment support method")
    reference = recipe.get("regional")
    if (not isinstance(reference, dict)
            or not re.fullmatch(r"watershed-[0-9a-f]{20}", str(reference.get("report_id", "")))
            or regional.get("id") != reference["report_id"]
            or not isinstance(regional.get("hucs"), list) or not regional["hucs"]):
        raise ValueError("Gauge report lost its original regional watershed membership")
    identifier(reference.get("sha256"))
    selection = analysis.get("selection")
    if not isinstance(selection, dict):
        raise ValueError("Gauge report must retain its original support selection")
    hucs = {str(row["huc12"]) for row in regional["hucs"]}
    if not set(selection.get("reporting_huc12s", [])) <= hucs:
        raise ValueError("Gauge report selects watersheds outside its original regional report")
    source_bindings = analysis.get("sources")
    if not isinstance(source_bindings, list) or not source_bindings:
        raise ValueError("Gauge report lost its original geographic and flow source bindings")
    station_build = identifier(analysis.get("station_build_id"))
    build_identity = {
        "version": analysis["version"], "selection": selection, "regional": reference,
        "station_build_id": station_build,
        "sources": [{name: row[name] for name in ("collection_id", "source_id", "source_sha256")}
                    for row in source_bindings],
    }
    if digest(build_identity) != build_id:
        raise ValueError("Gauge support source changed its immutable calculation identity")
    files = {}
    for descriptor in package.get("files", []):
        name = _member(descriptor["path"])
        captured = members.get("retained/" + name)
        if name in files or captured is None or not _same(descriptor, captured):
            raise ValueError("Gauge package lost an exact original member: " + name)
        files[name] = descriptor
    for name in ("analysis.json", "regional-report.json", "catchments.geojson",
                 "regional-hucs.geojson", "gauges.geojson", "original-station-geography.zip"):
        if name not in files:
            raise ValueError("Gauge report lacks its original " + name)
    for name in ("retained/gauge-support.zip", "maps/OPEN_GAUGE_MAPS.html"):
        if name not in members:
            raise ValueError("Gauge report lacks its original portable or geographic product")
    return key, build_id, station_id, package, analysis, regional, files


def _captured_sources(closure, members, package, analysis):
    """Verify packaged source manifests against exact original body/companion bindings."""
    bindings = {}
    for row in analysis["sources"]:
        collection_id = identifier(row.get("collection_id"))
        source_id = row.get("source_id")
        if not isinstance(source_id, str) or not source_id:
            raise ValueError("Gauge result needs an original native source identifier")
        token = (collection_id, source_id)
        if token in bindings or row.get("source_sha256") != row.get("body", {}).get("sha256"):
            raise ValueError("Gauge result repeats or changes an original source binding")
        bindings[token] = row
    actual = set()
    collections = set()
    for manifest_row in package.get("source_manifests", []):
        collection_id = identifier(manifest_row.get("original_collection_id"))
        if collection_id in collections:
            raise ValueError("Gauge package repeats an original source collection")
        collections.add(collection_id)
        prefix = "retained_sources/" + collection_id + "/"
        if (manifest_row.get("path") != prefix + "sources.json"
                or manifest_row.get("original_manifest_path") != prefix + "original_manifest.json"):
            raise ValueError("Gauge package changed its original source manifest path")
        manifest = _original(closure, members, "retained/" + manifest_row["path"])
        if manifest.get("schema") != "upstate.sources/v1":
            raise ValueError("Gauge package source manifest has another schema")
        _original(closure, members, "retained/" + manifest_row["original_manifest_path"])
        for entry in manifest.get("entries", []):
            source_id = entry.get("id")
            token = (collection_id, source_id)
            original = bindings.get(token)
            origin = {"collection_id": collection_id, "source_id": source_id,
                      "source_sha256": original["source_sha256"]} if original else None
            if original is None or token in actual or entry.get("origin_ref") != origin:
                raise ValueError("Gauge source manifest differs from its calculated source roster")
            metadata = original["source_metadata"]
            for field, value in metadata.items():
                # The maintained package writer reconstructs these receiving fields.
                # Their exact current values are verified against the binding below.
                if field in ("origin_ref", "path", "sha256", "companions"):
                    continue
                if entry.get(field) != value:
                    raise ValueError("Gauge source metadata changed: " + str(field))
            if entry.get("sha256") != original["source_sha256"]:
                raise ValueError("Gauge source manifest changed its original body")
            authored = [{"path": entry["path"], "sha256": entry["sha256"]},
                        *entry.get("companions", [])]
            retained = [original["body"], *original.get("companions", [])]
            if len(authored) != len(retained):
                raise ValueError("Gauge source manifest lost an original companion")
            for descriptor, before in zip(authored, retained):
                name = "retained/" + prefix + _member(descriptor["path"])
                captured = members.get(name)
                if (captured is None or not _same(captured, before)
                        or descriptor.get("sha256") != before["sha256"]):
                    raise ValueError("Gauge report changed an original geographic/flow source member")
            actual.add(token)
    if actual != set(bindings):
        raise ValueError("Gauge report omitted an original source collection or entry")
    return bindings


def _source_collections(closure, bindings):
    for (collection_id, source_id), binding in sorted(bindings.items()):
        value = closure.read("sources/" + collection_id + ".json")
        if value.get("schema") != "upstate.sources/v1" or digest(value) != collection_id:
            raise ValueError("Gauge editable source collection changed")
        matches = [row for row in value.get("entries", []) if row.get("id") == source_id]
        if len(matches) != 1:
            raise ValueError("Gauge editable source lost its exact original entry")
        entry = matches[0]
        metadata = {name: item for name, item in entry.items() if name not in ("body", "companions")}
        if (metadata != binding.get("source_metadata")
                or entry.get("body") != binding.get("body")
                or entry.get("companions", []) != binding.get("companions", [])):
            raise ValueError("Gauge report differs from its editable original source")
        closure.need("sources", collection_id, "Original Gauge geographic and flow sources")


def _saved_package(closure, prefix, record, schema):
    files = {}
    for item in record.get("files", []):
        path = _member(item["path"])
        if not path.startswith(prefix) or path in files:
            raise ValueError("Gauge study file leaves its original saved edition")
        closure.add_file(path, item)
        files[path] = item
    package_path = prefix + "package.json"
    if package_path not in files:
        raise ValueError("Gauge study lacks its original portable package")
    package = closure.read(package_path)
    if package.get("schema") != schema or package.get("build_id") != record["build_id"]:
        raise ValueError("Gauge study package has another original identity")
    for item in package.get("files", []):
        path = prefix + _member(item["path"])
        closure.add_file(path, item)
    pointer = closure.read(prefix + "edition.json")
    if pointer != {"id": record["id"], "build_id": record["build_id"]}:
        raise ValueError("Gauge study lost its original saved-edition pointer")
    return package, files


def _station(closure, key, captured, gauge_members):
    station = _immutable(closure, "station-geographies", key)
    if station["build_id"] != captured["station_build_id"]:
        raise ValueError("Gauge source and original Station Geography builds differ")
    prefix = "station-geography/" + identifier(station["build_id"]) + "/"
    package, files = _saved_package(closure, prefix, station, "upstate.station-geography-package/v1")
    if (package.get("project_id") != closure.workspace.project["id"]
            or package.get("selection") != station.get("selection")):
        raise ValueError("Station Geography package belongs to another original project/selection")
    analysis = closure.read(prefix + "analysis.json")
    if (analysis.get("schema") != "upstate.station-geography-result/v1"
            or analysis.get("project_id") != closure.workspace.project["id"]
            or analysis.get("build_id") != station["build_id"]
            or analysis.get("selection") != station["selection"]
            or analysis.get("sources") != station["sources"]):
        raise ValueError("Station Geography changed its original saved calculation")
    archive = files.get(prefix + "station-geography.zip")
    if archive is None or not _same(archive, gauge_members["retained/original-station-geography.zip"]):
        raise ValueError("Gauge report and editable Station Geography archives differ")
    source_bindings = {(row["collection_id"], row["source_id"]): row for row in station["sources"]}
    _source_collections(closure, source_bindings)
    for observation_id in station.get("observation_ids", []):
        closure.need("observations", identifier(observation_id), "Original Station Geography observations")
    collection_id = station.get("source_collection_id")
    if collection_id:
        closure.need("sources", identifier(collection_id), "Original Station Geography spatial layers")
    closure.tree(prefix.rstrip("/"))
    return station


def _regional(closure, reference, captured):
    key = reference["report_id"]
    prefix = "watershed-context/" + key + "/"
    record = closure.read(prefix + "operator-report.json")
    if (record.get("schema") != "upstate.operator-watershed-context/v1"
            or record.get("id") != key or record.get("state") != "complete"
            or record.get("source_fingerprint") != reference.get("source_fingerprint")):
        raise ValueError("Gauge report and retained regional report have different identities")
    files = record.get("files")
    if not isinstance(files, dict):
        raise ValueError("Original regional report lacks its full member inventory")
    for name, item in files.items():
        relative = _member(item.get("path", name))
        closure.add_file(prefix + relative, item)
    descriptor = files.get("watershed-context.json")
    if descriptor is None or descriptor.get("sha256") != reference["sha256"]:
        raise ValueError("Gauge report changed its original regional result bytes")
    if closure.read(prefix + "watershed-context.json") != captured:
        raise ValueError("Gauge source changed its captured original regional result")
    edition = reference.get("source_edition_fingerprint")
    if edition and (record.get("source_edition_fingerprint") != edition
                    and edition not in record.get("source_editions", {})):
        raise ValueError("Gauge study lost its originally selected regional source edition")
    # Retain the complete local original-source copies and appended source editions.
    # Absolute acquisition paths are provenance; the operator reopens this saved tree.
    closure.tree(prefix.rstrip("/"))
    closure._source_refs(record, "Original regional watershed source collections")
    return record


def _report_capture(closure, entry, recipe, members, build_id, gauge_id):
    base = "gauge-support/" + build_id + "/report-context"
    folder = closure.root / base
    candidates = []
    source_suffix = entry["id"].removeprefix("gauge-support-report-")
    if len(source_suffix) != 20 or not re.fullmatch(r"[0-9a-f]{20}", source_suffix):
        raise ValueError("Gauge report source lost its original operation identifier")
    if folder.is_symlink() or not folder.is_dir():
        raise ValueError("Gauge report lacks its original native source capture")
    for directory in sorted(folder.iterdir()):
        if (directory.is_dir() and not directory.is_symlink()
                and re.fullmatch(r"[0-9a-f]{64}", directory.name)
                and directory.name.startswith(source_suffix)):
            candidates.append(directory.name)
    if len(candidates) != 1:
        raise ValueError("Choose the exact original Gauge report capture")
    operation_id = candidates[0]
    prefix = base + "/" + operation_id + "/"
    record = closure.read(prefix + "registered-context.json")
    if (record.get("schema") != "upstate.gauge-report-context/v1"
            or record.get("operation_id") != operation_id
            or record.get("workspace_id") != recipe["project_id"]
            or record.get("gauge_support_id") != gauge_id
            or record.get("gauge_build_id") != build_id
            or record.get("source_id") != entry["id"]):
        raise ValueError("Gauge report lost its original registered source capture")
    source = record.get("source")
    if not isinstance(source, dict) or source.get("source_id") != entry["id"]:
        raise ValueError("Gauge report capture lacks its original source selector")
    source_collection = identifier(source.get("source_collection_id"))
    collection = closure.read("sources/" + source_collection + ".json")
    entries = [row for row in collection.get("entries", []) if row.get("id") == entry["id"]]
    if (collection.get("schema") != "upstate.sources/v1" or digest(collection) != source_collection
            or len(entries) != 1 or not _same(entries[0]["body"], entry["body"])):
        raise ValueError("Gauge report lost its original imported source edition")
    closure.need("sources", source_collection, "Original registered Gauge scientific report")
    for descriptor in record.get("files", []):
        path = _member(descriptor["path"])
        if not path.startswith(prefix):
            raise ValueError("Gauge report capture member belongs to another operation")
        closure.add_file(path, descriptor)
    if closure.read(prefix + "gauge-report.json") != recipe:
        raise ValueError("Gauge report source differs from its native recipe")
    closure.add_file(prefix + "gauge-report.json", entry["body"])
    for name, descriptor in members.items():
        closure.add_file(prefix + name, descriptor)
    closure.tree(prefix.rstrip("/"))
    return operation_id


def include_source(closure, collection_id, entry):
    """Retain complete Gauge lineage only for an explicitly selected report source."""
    metadata = entry.get("metadata") or {}
    if metadata.get("report_context_kind") != CONTEXT and entry.get("role") != ROLE:
        return False
    identifier(collection_id)
    recipe = _body(closure, entry["body"])
    if (entry.get("kind") != "document" or entry.get("role") != ROLE
            or metadata.get("report_schema") != REPORT_SCHEMA
            or recipe.get("schema") != REPORT_SCHEMA
            or recipe.get("report_context_kind") != CONTEXT
            or recipe.get("edition") not in REPORT_EDITIONS):
        raise ValueError("Gauge report differs from its declared original producer")
    project = recipe.get("project_id")
    if not isinstance(project, str) or not project:
        raise ValueError("Gauge report lacks its original project identity")
    gauge_id = identifier(recipe.get("gauge_support_id"))
    if (entry.get("uri") != "workspace://" + project + "/gauge-support/" + gauge_id
            or metadata.get("gauge_support_id") != gauge_id
            or metadata.get("regional_report_id") != (recipe.get("regional") or {}).get("report_id")):
        raise ValueError("Gauge report changed its source, project or regional identity")
    members = _members(closure, entry, recipe)
    key, build_id, station_id, package, analysis, regional, files = _package(closure, members, recipe)
    source_bindings = _captured_sources(closure, members, package, analysis)
    local = project == closure.workspace.project["id"]
    required, operation_id = [], None
    if local:
        gauge = _immutable(closure, "gauge-support", key)
        if any(gauge.get(name) != analysis.get(name) for name in (
                "version", "title", "created_at", "build_id", "selection", "summary",
                "regional", "station_edition_id", "sources")):
            raise ValueError("Gauge source and original editable edition differ")
        prefix = "gauge-support/" + build_id + "/"
        local_package, saved_files = _saved_package(closure, prefix, gauge, PACKAGE_SCHEMA)
        if local_package != package:
            raise ValueError("Gauge source and original editable package differ")
        for name, descriptor in members.items():
            if name.startswith("retained/"):
                closure.add_file(prefix + name[len("retained/"):], descriptor)
        if closure.read(prefix + "analysis.json") != analysis:
            raise ValueError("Gauge source changed its original calculated values")
        _source_collections(closure, source_bindings)
        station = _station(closure, station_id, analysis, members)
        regional_record = _regional(closure, recipe["regional"], regional)
        operation_id = _report_capture(closure, entry, recipe, members, build_id, gauge_id)
        required = [{"kind": "gauge-support", "id": gauge_id},
                    {"kind": "station-geographies", "id": station_id},
                    {"kind": "watershed-context", "id": recipe["regional"]["report_id"]}]
        for kind, record, title in (
                ("gauge-support", gauge, "Original Gauge support"),
                ("station-geographies", station, "Original Station Geography"),
                ("watershed-context", regional_record, "Original regional watershed context")):
            closure.nodes.setdefault((kind, record["id"]), {
                "kind": kind, "id": record["id"], "state": "complete",
                "title": record.get("title") or title,
                "reasons": ["Editable source of the selected Gauge scientific report"],
            })
    binding = {
        "schema": "upstate.study-report-lineage/v1", "report_context_kind": CONTEXT,
        "source_collection_id": collection_id, "source_id": entry["id"],
        "source_body_sha256": entry["body"]["sha256"], "source_project_id": project,
        "gauge_support_id": gauge_id, "gauge_build_id": build_id,
        "station_edition_id": station_id, "station_build_id": analysis["station_build_id"],
        "regional": deepcopy(recipe["regional"]), "producer_edition": recipe["edition"],
        "source_choices": [{"source_collection_id": key[0], "source_id": key[1],
                            "source_body_sha256": row["source_sha256"]}
                           for key, row in sorted(source_bindings.items())],
        "support": deepcopy(recipe.get("support", analysis.get("support"))),
        "original_selection": deepcopy(recipe["original_selection"]),
        "relationship": "same_project" if local else "external_project",
        "native_report_operation_id": operation_id, "required_records": required,
    }
    token = (collection_id, entry["id"])
    previous = closure.report_source_records.get(token)
    if previous is not None and previous != binding:
        raise ValueError("Gauge scientific source changed during selected-study capture")
    closure.report_source_records[token] = binding
    return True


def lock_paths(closure):
    """Return only the actual report producer locks for retained local captures.

    Study capture already holds the original Workspace lock used by regional
    source updates. Gauge and Station Geography records/packages are immutable.
    """
    return sorted({
        "locks/gauge-report-" + identifier(row["native_report_operation_id"]) + ".lock"
        for row in closure.report_source_records.values()
        if row.get("report_context_kind") == CONTEXT
        and row.get("relationship") == "same_project"
        and row.get("native_report_operation_id")
    })

"""Scientific support of retained measurements and native catchment comparisons."""
from __future__ import annotations
from collections import Counter
from decimal import Decimal
import json
import re

FIELDS = (
    "measurement_support", "species", "facility_id", "facility_name", "outfall_id",
    "reporting_feature", "monitoring_location", "parameter_code", "gauge_id",
    "gauge_relation", "relation_method", "quantity_basis", "coverage_days",
    "expected_days", "coverage_complete", "coverage_detail", "source_quantity",
)
SUPPORTS = {
    "catchment_export": "Receiving-water catchment export",
    "point_source_discharge": "Observed point-source discharge",
    "concentration": "Observed concentration",
    "other_context": "Other original measurement context",
}
SPECIES = {
    "nitrogen": {"nitrogen", "total nitrogen", "nitrogen total", "total nitrogen as n",
                 "nitrogen total as n", "tn", "00600", "epa 00600"},
    "phosphorus": {"phosphorus", "total phosphorus", "phosphorus total",
                   "total phosphorus as p", "phosphorus total as p", "tp", "00665", "epa 00665"},
    "sediment": {"sediment", "total sediment"},
}


KIND_SUPPORTS = {
    "reported_effluent_source_amount": "point_source_discharge",
    "complete_reported_effluent_source_amount": "point_source_discharge",
    "receiving_water_measurement": "concentration",
    "receiving_water_derived_concentration": "concentration",
}


def species_key(value):
    return re.sub(r"[\s_,()\[\]\-]+", " ", str(value).strip().lower()).strip()


def source_species(row, metadata):
    declared = row.get("species") or metadata.get("species")
    if declared:
        return str(declared)
    original = row.get("original_parameter")
    if not original and isinstance(row.get("original"), dict):
        field = metadata.get("columns", {}).get("parameter", "parameter")
        original = row["original"].get(field)
    return str(original or row.get("parameter") or "")


def detail(value):
    if value in (None, ""):
        return None
    if not isinstance(value, str):
        return value
    try:
        return json.loads(value, parse_constant=lambda token: (_ for _ in ()).throw(ValueError(token)))
    except (ValueError, TypeError):
        return value


def attributes(cell, metadata, parameter):
    result = {}
    for key in FIELDS:
        value = cell(key)
        if value in (None, ""):
            value = metadata.get(key)
        if value not in (None, ""):
            result[key] = detail(value) if key in ("coverage_detail", "source_quantity") else value
    explicit = result.get("measurement_support")
    annual = metadata.get("value_basis") == "annual_mass_rate"
    kind = metadata.get("observation_kind")
    kind_support = KIND_SUPPORTS.get(kind)
    result["measurement_support"] = explicit or kind_support or (
        "catchment_export" if annual else "other_context")
    result["support_origin"] = ("explicit_source" if explicit else
                               "declared_context_kind" if kind_support or not annual else
                               "legacy_catchment_import_contract")
    declared_species = result.get("species")
    result["original_parameter"] = cell("parameter") or parameter
    result["species"] = str(declared_species or result["original_parameter"])
    result["species_origin"] = "explicit_source" if declared_species else "original_parameter"
    result["quantity_basis"] = result.get("quantity_basis") or metadata.get("value_basis", "context")
    facility = metadata.get("facility_registry", {}).get(result.get("facility_id"), {})
    for key in ("facility_name", "outfall_id", "relation_method"):
        if key not in result and facility.get(key) is not None:
            result[key] = facility[key]
    if result.get("gauge_relation") and facility.get("gauge_relation") not in (None, result["gauge_relation"]):
        raise ValueError("The retained facility and quantity gauge relationships differ")
    if result["measurement_support"] not in SUPPORTS:
        raise ValueError("Unknown measurement_support: " + str(result["measurement_support"]))
    for key in ("coverage_days", "expected_days"):
        if key in result:
            value = Decimal(str(result[key]))
            if not value.is_finite() or value < 0 or value != value.to_integral_value():
                raise ValueError(key + " must be an original nonnegative integer day count")
            result[key] = int(value)
    if "coverage_complete" in result:
        value = result["coverage_complete"]
        if value in (True, "true", "True", "1", 1):
            result["coverage_complete"] = True
        elif value in (False, "false", "False", "0", 0):
            result["coverage_complete"] = False
        else:
            raise ValueError("coverage_complete must be true or false")
    return result


def measurement_support(row, metadata=None):
    metadata = metadata or {}
    return (row.get("measurement_support") or metadata.get("measurement_support")
            or KIND_SUPPORTS.get(metadata.get("observation_kind"))
            or ("catchment_export" if metadata.get("value_basis", "annual_mass_rate") == "annual_mass_rate"
                else "other_context"))


def comparison_issues(row, metadata=None):
    metadata = metadata or {}
    support = measurement_support(row, metadata)
    issues = []
    if support != "catchment_export":
        issues.append("Retained " + SUPPORTS.get(support, str(support)).lower()
                      + "; native landscape catchment export is a different quantity")
    kind_support = KIND_SUPPORTS.get(metadata.get("observation_kind"))
    if kind_support and kind_support != support:
        issues.append("Original source kind declares " + SUPPORTS[kind_support].lower()
                      + "; the selected measurement support conflicts with that source")
    parameter = row.get("parameter")
    species = source_species(row, metadata)
    if parameter in SPECIES and species_key(species) not in SPECIES[parameter]:
        issues.append("Original species " + species + " differs from native total " + parameter)
    basis = row.get("quantity_basis") or metadata.get("value_basis", "context")
    if basis != "annual_mass_rate":
        issues.append("The original quantity is not an explicitly derived annual mass rate")
    if basis == "annual_mass_rate":
        complete = row.get("coverage_complete", metadata.get("coverage_complete"))
        if complete in (False, "false", "False", "0", 0):
            issues.append("Source declares incomplete coverage; retain its quantified-period quantity")
        counts = {}
        for key in ("coverage_days", "expected_days"):
            value = row.get(key)
            if value in (None, ""):
                value = metadata.get(key)
            if value in (None, ""):
                continue
            try:
                count = Decimal(str(value))
                if (not count.is_finite() or count < 0
                        or count != count.to_integral_value()):
                    raise ValueError()
                counts[key] = int(count)
            except (ArithmeticError, ValueError, TypeError):
                issues.append("Original " + key + " is not a nonnegative integer day count")
        if any(value == 0 for value in counts.values()):
            issues.append("Source declares zero coverage or expected days; annual catchment comparison needs nonempty coverage")
        if ("coverage_days" in counts and "expected_days" in counts
                and counts["coverage_days"] != counts["expected_days"]):
            issues.append(
                f"Source coverage is {counts['coverage_days']} of {counts['expected_days']} expected days; "
                "annual catchment comparison requires complete declared coverage")
    return issues



def admission_projection(rows, metadata=None):
    """Describe current source eligibility without changing retained import rows."""
    metadata = metadata or {}
    eligible, reasons = [], {}
    originally_admitted = 0
    for row in rows:
        original = bool(row.get("admitted"))
        originally_admitted += int(original)
        support_issues = comparison_issues(row, metadata)
        native_parameter = row.get("parameter") in SPECIES
        if original and native_parameter and not support_issues:
            eligible.append(row)
            continue
        issues = list(row.get("issues", [])) + support_issues
        if not native_parameter:
            issues.append("This measurement is outside the native N/P/sediment annual-load comparison")
        if not original and not issues:
            issues.append("The retained import did not admit this original row as an annual catchment load")
        for issue in dict.fromkeys(issues):
            reasons.setdefault(issue, []).append(row["id"])
    return {
        "schema": "upstate.observation-source-admission/v1",
        "source_row_count": len(rows),
        "original_admitted_count": originally_admitted,
        "eligible_count": len(eligible),
        "excluded_count": len(rows) - len(eligible),
        "previously_admitted_now_excluded": originally_admitted - len(eligible),
        "eligible_record_ids": [row["id"] for row in eligible],
        "parameters": sorted({row["parameter"] for row in eligible}),
        "catchment_ids": sorted({row["catchment_id"] for row in eligible}),
        "exclusion_reasons": [
            {"reason": reason, "count": len(ids), "observation_record_ids": ids}
            for reason, ids in reasons.items()
        ],
        "basis": "Current source admission requires the original import's admission plus current "
                 "measurement-support, constituent, quantity and declared-coverage rules. "
                 "Original rows remain unchanged. Native model availability, catchment identity "
                 "and raster coverage are evaluated separately. A row can have several exclusion reasons.",
    }

def summarize(rows):
    kinds = Counter(row.get("measurement_support", "catchment_export") for row in rows)
    return {
        "counts": dict(kinds),
        "titles": {key: SUPPORTS.get(key, key) for key in kinds},
        "native_comparison_count": sum(row.get("admitted", False) for row in rows),
        "point_source_count": kinds.get("point_source_discharge", 0),
        "legacy_catchment_contract_count": sum(
            row.get("support_origin") == "legacy_catchment_import_contract" for row in rows),
        "interpretation": "Facility discharge, receiving-water catchment load and concentration "
                          "retain their original support. Native residuals compare like annual catchment "
                          "quantities. Point-source quantities remain dated context with original species, "
                          "reporting feature, gauge relation and quantified coverage.",
    }


def context_record(row, metadata=None):
    """Keep original quantities available when a native fit statistic is inappropriate."""
    metadata = metadata or {}
    return {
        "observation_id": row["id"],
        **{key: row.get(key) for key in FIELDS if key in row},
        "measurement_support": measurement_support(row, metadata),
        "species": source_species(row, metadata),
        "original_parameter": row.get("original_parameter"),
        "species_origin": row.get("species_origin"),
        "station_id": row.get("station_id"), "catchment_id": row.get("catchment_id"),
        "parameter": row.get("parameter"), "value_text": row.get("value_text"),
        "unit": row.get("unit"), "period_start": row.get("period_start"),
        "period_end": row.get("period_end"), "method": row.get("method"),
        "qualifier": row.get("qualifier"), "uncertainty": row.get("uncertainty"),
        "source_records": row.get("source_records"), "original": row.get("original"),
        "comparison_issues": list(dict.fromkeys([*row.get("issues", []),
                                                  *comparison_issues(row, metadata)])),
    }


REFERENCE_BASIS_VERSION = "upstate.annual-reference-basis/v1"
REFERENCE_METHOD_SOURCE = "https://pubs.usgs.gov/publication/wri004191"
_REFERENCE_CODES = {
    "00600": ("nitrogen", "Total nitrogen", "total_nitrogen"),
    "00665": ("phosphorus", "Total phosphorus", "total_phosphorus"),
    "00530": ("sediment", "Total suspended solids (TSS)", "tss"),
    "80154": ("sediment", "Suspended-sediment concentration (SSC) based load", "ssc"),
}
_REFERENCE_ALIASES = {
    "tn": "00600", "total nitrogen": "00600",
    "tp": "00665", "total phosphorus": "00665",
    "tss": "00530", "total suspended solids": "00530",
    "ssc": "80154", "suspended sediment": "80154",
    "suspended sediment concentration": "80154",
}


def reference_basis(row, metadata=None):
    """Describe retained constituent evidence without changing admission or mass."""
    metadata = metadata or {}
    evidence = []
    def read(value, path):
        value = detail(value)
        if not isinstance(value, dict):
            return
        for field in ("parameter_code", "series", "source_constituent", "species"):
            token = value.get(field)
            if token in (None, ""):
                continue
            key = species_key(token)
            code = (str(token).strip().zfill(5) if re.fullmatch(r"[0-9]{1,5}", str(token).strip())
                    else _REFERENCE_ALIASES.get(key))
            if code in _REFERENCE_CODES:
                evidence.append({"field": path + field, "original_value": token, "parameter_code": code})
        for field in ("row", "original_attributes"):
            original = value.get(field)
            if isinstance(original, dict) and original.get("CONSTITUEN") not in (None, ""):
                token = original["CONSTITUEN"]
                code = _REFERENCE_ALIASES.get(species_key(token))
                if code:
                    evidence.append({"field": path + field + ".CONSTITUEN",
                                     "original_value": token, "parameter_code": code})
    read(row, "")
    read(metadata, "metadata.")
    sources = detail(row.get("source_records"))
    sources = sources if isinstance(sources, list) else [sources]
    for index, source in enumerate(sources):
        read(source, "source_records[" + str(index) + "].")
    codes = sorted({item["parameter_code"] for item in evidence})
    parameter = row.get("parameter")
    constituents = [{"parameter_code": code, "parameter": _REFERENCE_CODES[code][0],
                     "label": _REFERENCE_CODES[code][1], "basis": _REFERENCE_CODES[code][2]}
                    for code in codes]
    inconsistent = any(item["parameter"] != parameter for item in constituents)
    status = ("conflicting_parameter" if inconsistent else
              "mixed_source_constituents" if len(codes) > 1 else
              "declared_original_constituent" if codes else "not_declared")
    label = "; ".join(item["label"] + " [" + item["parameter_code"] + "]" for item in constituents)
    if not label:
        label = source_species(row, metadata) or str(parameter or "Unspecified constituent")
    notes = []
    if "00530" in codes:
        notes.append("The annual reference is derived from TSS measurements. TSS and whole-sample SSC "
                     "are different analytical bases and are not interchangeable; a residual against "
                     "native sediment export also reflects that source-method difference.")
    if "80154" in codes:
        notes.append("The annual reference is derived from suspended-sediment measurements. Retain its "
                     "sampling and estimator support when interpreting native hillslope delivery to streams.")
    if "00530" in codes or "80154" in codes:
        notes.append("Original annual values and any published TSS_CONV field remain unchanged. "
                     "This report does not apply an inferred TSS-to-SSC or outlet-transport conversion.")
    if status == "mixed_source_constituents":
        notes.append("This retained reference combines more than one declared constituent basis. "
                     "Its original aggregate remains visible; it is not relabeled as one analytical method.")
    elif inconsistent:
        notes.append("The retained constituent evidence differs from the selected native parameter; "
                     "inspect the original source fields alongside the unchanged comparison.")
    elif not codes and parameter == "sediment":
        notes.append("The retained fields do not identify a specific TSS or SSC analytical basis.")
    return {"schema": REFERENCE_BASIS_VERSION, "parameter": parameter, "status": status,
            "label": label, "parameter_codes": codes, "constituents": constituents,
            "source_fields": evidence, "interpretation": " ".join(notes),
            "method_references": [REFERENCE_METHOD_SOURCE] if any(c in codes for c in ("00530", "80154")) else [],
            "quantity_transformation": "none; retained annual quantities and comparison eligibility are unchanged"}


def reference_basis_rows(rows, metadata=None):
    """One source-aware description per original comparison/reference unit."""
    result = []
    for row in rows:
        basis = reference_basis(row, metadata)
        result.append({
            "reference_id": row.get("unit_id") or row.get("id") or row.get("observation_id"),
            "parameter": row.get("parameter"), "catchment_id": row.get("catchment_id"),
            "station_id": row.get("station_id"), "observation_record_ids": row.get("observation_record_ids"),
            "period_start": row.get("period_start"), "period_end": row.get("period_end"),
            "reference_label": basis["label"], "parameter_codes": basis["parameter_codes"],
            "reference_status": basis["status"], "interpretation": basis["interpretation"],
            "source_fields": basis["source_fields"], "method_references": basis["method_references"],
        })
    return result


def reference_basis_blocks(rows, metadata=None):
    """Readable report blocks from the same retained reference descriptions."""
    summaries = {}
    for row in reference_basis_rows(rows, metadata):
        key = (row["parameter"], row["reference_label"], row["reference_status"])
        item = summaries.setdefault(key, {**row, "records": 0})
        item["records"] += 1
    if not summaries:
        return []
    blocks = [
        "Original reference constituents. Annual mass units do not make different analytical "
        "methods equivalent. The source labels below accompany the retained comparisons and their "
        "existing objective; source values, admitted rows and native results keep their identities.",
        {"kind": "table", "columns": ["Native parameter", "Original reference basis", "Retained rows", "Interpretation"],
         "rows": [[str(item["parameter"]), item["reference_label"], str(item["records"]),
                   item["interpretation"] or "Original constituent identity retained."]
                  for item in summaries.values()]},
    ]
    if any(item["method_references"] for item in summaries.values()):
        blocks.append("Source-method reference: USGS, Comparability of suspended-sediment concentration "
                      "and total suspended solids data (2000), " + REFERENCE_METHOD_SOURCE + ".")
    return blocks
